import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"灰度光刻","description":"","frontmatter":{"title":"灰度光刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/grayscale-litho.md","filePath":"litho/grayscale-litho.md","lastUpdated":1789023840000}'),E={name:"litho/grayscale-litho.md"};function c(_,a,m,B,u,A){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="灰度光刻" tabindex="-1">灰度光刻 <a class="header-anchor" href="#灰度光刻" aria-label="Permalink to &quot;灰度光刻&quot;">​</a></h1><div class="epigraph"><p>二元掩模只印「有/无」；灰度把局部剂量映射成胶的剩余厚度，一次曝光做出斜面和微透镜。</p><footer>—— 对照 grayscale lithography 与剂量调制三维胶轮廓的通称</footer></div><p><a href="/litho/mems-patterning">上一课</a>需要三维结构。缺口是如何不用许多层二元曝光去堆斜面。本课钉灰度光刻。双光子把三维做到体素，留给[下一课](/litho/two-photon-3d）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>灰度：掩模透过率连续或分多档，或激光直写调功率，使胶在显影后高度随剂量变。用于微透镜阵列、DOE、MEMS 斜面。校准是胶的对比度曲线（γ）与显影，薄膜驻波会调制高度——轨道与薄膜课的物理在此变成高度噪声。</p><p>缺口是<strong>剂量→高度</strong>，不是平面 CD。把灰度当 OPC 的剂量 MPC，对象错了：这里高度是产品。</p><h3 id="与-vsb-灰度炮的区别" tabindex="-1">与 VSB 灰度炮的区别 <a class="header-anchor" href="#与-vsb-灰度炮的区别" aria-label="Permalink to &quot;与 VSB 灰度炮的区别&quot;">​</a></h3><p>掩模写入灰度是为了斜边逼近；本课是晶圆/器件灰度。同词不同层。</p><p><span class="marginnote">低 γ 胶对灰度友好（高度渐变），对 IC 锐边不友好。胶不能两头讨好。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：透过率图或激光位图。校准：台阶高度计或光学轮廓。工艺：厚胶、软烘、显影终点。转印：有时再回流（resist reflow 课）把台阶熔成光滑透镜。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>剩余厚度是溶解速率对剂量积分的结果。驻波给出 z 方向条纹，灰度表面变「波纹」。抗反射与烘烤与 IC 相同物理，规格源换成表面 rms。</p>',13)),(e(),n(p,null,{default:r(()=>[d(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E9%80%8F%E8%BF%87%E7%8E%87%20%2F%20%E6%BF%80%E5%85%89%E5%8A%9F%E7%8E%87%22%5D%20--%3E%20D%5B%22%E5%B1%80%E9%83%A8%E5%89%82%E9%87%8F%22%5D%0A%20%20D%20--%3E%20Z%5B%22%E5%89%A9%E4%BD%99%E8%83%B6%E5%8E%9A%22%5D%0A%20%20SW%5B%22%E9%A9%BB%E6%B3%A2%22%5D%20--%3E%20RIP%5B%22%E9%AB%98%E5%BA%A6%E6%B3%A2%E7%BA%B9%22%5D%0A%20%20Z%20--%3E%20DEV%5B%22%E5%BE%AE%E9%80%8F%E9%95%9C%20%2F%20%E6%96%9C%E9%9D%A2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>灰度不服务 MMP 逻辑。动态范围受胶 γ 与掩模档数限制。不把 3D IC 的多层金属当灰度。</p><p>后课默认：二维剂量可映射高度；下一课非线性双光子把曝光关在焦点体素里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>灰度光刻把剂量写成胶高度，服务微光学与 MEMS 斜面。</li><li>胶 γ 与驻波决定高度精度。</li><li>与掩模写入灰度同词不同对象。</li><li>出处：grayscale lithography 通称。</li></ul>',5))])}const b=l(E,[["render",c]]);export{D as __pageData,b as default};
